const item = $input.first().json;
const payload = item.body ? item.body : item;

const sender = payload.sender_email || payload.from || "guest@enterprise.com";
const senderName = payload.sender_name || payload.name || sender.split('@')[0];
const title = payload.subject || payload.title || "Yêu cầu hỗ trợ kỹ thuật";
const description = payload.body || payload.text || payload.raw_description || "Không có mô tả chi tiết";
const category = payload.category || "Technical";
const priority = payload.priority || "P1 - Critical";

return [{
  json: {
    ...payload,
    sender_email: sender,
    sender_name: senderName,
    title: title,
    description: description,
    category: category,
    priority: priority
  }
}];

const randomCode = Math.floor(1000 + Math.random() * 9000);
const ticketCode = `TICK-2026-${randomCode}`;
const current = $input.first().json;

return [{
  json: {
    ...current,
    ticket_code: ticketCode,
    generated_at: new Date().toISOString()
  }
}];

const base = $('3. Generate Ticket ID Code').first().json;
const agentQuery = $input.first().json;

const assignedTo = agentQuery.name || "Nguyễn Văn An";
const agentEmail = agentQuery.email || "tranglee12306@gmail.com";

let slaHours = 8;
if (base.priority.includes('P1')) slaHours = 2;
else if (base.priority.includes('P2')) slaHours = 4;
else if (base.priority.includes('P3')) slaHours = 8;
else if (base.priority.includes('P4')) slaHours = 24;

const slaDeadline = new Date(Date.now() + slaHours * 3600 * 1000).toISOString();
const summary = base.description.length > 200 ? base.description.substring(0, 197) + '...' : base.description;

return [{
  json: {
    ...base,
    assigned_to: assignedTo,
    agent_email: agentEmail,
    first_response_sla: slaDeadline,
    summary: summary,
    sla_hours: slaHours
  }
}];

